parameters.jsCode:
const raw = String($json.text || '').replace(/```json|```/g, '').trim();
let data = null; const problems = [];
try { data = JSON.parse(raw); } catch (e) { problems.push('Response was not valid JSON'); }
if (data) {
  const required = ['full_name','email','phone','company','country','signup_date'];
  for (const f of required) { if (!(f in data)) problems.push('Missing field: ' + f); }
  if (data.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(data.email))) problems.push('email is not a valid address');
  if (data.phone && !/^\+[0-9]{8,15}$/.test(String(data.phone))) problems.push('phone is not E.164 format');
  if (data.signup_date && !/^\d{4}-\d{2}-\d{2}$/.test(String(data.signup_date))) problems.push('signup_date is not YYYY-MM-DD');
}
return { valid: problems.length === 0, problems: problems.join('; '), rawOutput: raw, data: data || {} };

